-- ALTER SHARE. https://docs.databricks.com/aws/en/sql/language-manual/sql-ref-syntax-ddl-alter-share
ALTER SHARE s ADD TABLE t;

ALTER SHARE s ADD SCHEMA sc;

ALTER SHARE s REMOVE TABLE t;

ALTER SHARE s RENAME TO s2;

ALTER SHARE s OWNER TO `u`;

ALTER SHARE s ADD TABLE t COMMENT 'c' PARTITION (p = 1) AS ss.st WITH HISTORY;

ALTER SHARE s ALTER TABLE t WITHOUT HISTORY;

ALTER SHARE s ADD MATERIALIZED VIEW mv AS smv;

ALTER SHARE s ADD VIEW v;

ALTER SHARE s ADD MODEL m;

ALTER SHARE s REMOVE SCHEMA sc;
